function storefrontPrice(id) {
  const regular = priceReferences[id];
  const sale = window.lepetseSales?.get(id);
  const now = Date.now();
  if (!regular || !sale || sale.amountMinor >= regular.amountMinor
      || now < Date.parse(sale.startsAt) || now >= Date.parse(sale.endsAt)) return regular;
  return {...regular, amountMinor: sale.amountMinor, regularAmountMinor: regular.amountMinor};
}
function saleMarkup(price) {
  return price.regularAmountMinor === undefined ? '' :
    ` <del class="regular-sale-price">${schoolMoney(price.regularAmountMinor)}</del> <span class="sale-badge">Sale</span>`;
}
function priceMarkup(p,detail=false){if(rfqBuyer())return '';const price=storefrontPrice(p.id);if(!price)return `<p class="reference-price price-unavailable">Price on request</p>`;const amount=new Intl.NumberFormat('en-ZA',{style:'currency',currency:price.currency}).format(price.amountMinor/100);return `<div class="reference-price"><span>Indicative price</span><strong>${esc(amount)}</strong>${saleMarkup(price)}<small>${p.unit==='Each'?'each':'per '+esc(p.unit.toLowerCase())}</small></div>${detail?`<p class="help">${quotationMode()?'Final price by quotation. Delivery excluded.':'Final price and delivery charges are to be confirmed.'}</p><details class="price-basis"><summary>Price reference</summary><p>Retail benchmark checked ${esc(price.checkedOn)} at <a href="${esc(price.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(price.retailer)}</a>.</p><p>${esc(price.referenceProduct)}</p><p>${esc(price.basis)}</p><p>${esc(price.taxBasis)} Retail promotions may change. This does not confirm Lepetse stock or selling prices.</p></details>`:''}`}
function productBrand(p){return /^(?:To be confirmed|Not specified|Brand to be confirmed)$/i.test(p.brand)?"Brand to be confirmed":p.brand}
function productArt(p){if(p.catalogueImport){if(!p.image)return `<div class="product-placeholder imported-photo-pending">${icon(p.category)}<span>Photo pending</span></div>`;return `<img src="${esc(p.image)}" alt="${esc(p.name)}${p.imageStatus==='reference'?' — reference product photograph':' — product photograph'}" width="700" height="700" loading="lazy" decoding="async">${p.imageStatus==='reference'?'<span class="reference-image-badge">Reference image</span>':''}`}return p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}${p.imageType==='supplier product photograph'?' — product photograph':' — generated illustrative product image'}" width="900" height="900" loading="lazy" decoding="async">`:`<div class="product-placeholder">${icon(p.category)}<span>Illustration</span></div>`}
function importedProductPhotoNote(p){if(!p.image)return 'An exact product photograph is not yet available. Brand, specification, pack contents and availability will be confirmed in your quotation.';return `${p.imageStatus==='reference'?'Reference photo only; the final model, colour, packaging and ordering unit require confirmation.':'Product photo from the referenced catalogue; final packaging and availability require confirmation.'} <a href="${esc(p.imageReference.url)}" target="_blank" rel="noopener noreferrer">Image source: ${esc(p.imageReference.retailer)}</a>.`}

function cardName(p){const brand=productBrand(p);if(brand==='Brand to be confirmed')return p.name;let name=p.name;if(name.toLowerCase().startsWith('waltons '+brand.toLowerCase()+' '))name=name.slice(8);const prefix=brand.split(/[^a-z0-9]+/i).filter(Boolean).join('[\\s-]+');return name.replace(new RegExp('^'+prefix+'\\s+','i'),'')}
function cardSpecification(p){const unit=p.unit.toLowerCase();return p.summary.split(/\s*·\s*/).filter(part=>{const text=part.toLowerCase();return text!=='each'&&text!==unit&&!(/^(?:pack|set|box) of \d+$/i.test(part)&&unit.startsWith(text))}).join(' · ')}
function cardPrice(p){if(rfqBuyer())return `<p class="unit-label">Order unit: ${esc(p.unit)}</p>`;const price=storefrontPrice(p.id);const unit=p.unit==='Each'?'each':'per '+p.unit.toLowerCase();if(!price)return `<div class="card-price"><div class="card-price-line"><strong class="on-request">Price on request</strong></div><small>${esc(unit)}</small></div>`;const amount=new Intl.NumberFormat('en-ZA',{style:'currency',currency:price.currency}).format(price.amountMinor/100);return `<div class="card-price"><div class="card-price-line"><strong>${esc(amount)}</strong>${saleMarkup(price)}<span>${esc(unit)}</span></div>${quotationMode()?'<small>Indicative price · final price by quotation</small>':''}</div>`}
function productCard(p){return `<article class="product-card"><a class="product-image" href="${productIntentHref(p.id)}" aria-label="View ${esc(p.name)}">${productArt(p)}</a><div class="product-body"><span class="product-brand">${esc(productBrand(p))}</span><h3><a href="${productIntentHref(p.id)}" title="${esc(p.name)}">${esc(cardName(p))}</a></h3><p class="card-specification" title="${esc(cardSpecification(p))}">${esc(cardSpecification(p))}</p>${cardPrice(p)}<div class="product-controls"><label class="sr-only" for="qty-${p.id}">Quantity for ${esc(p.name)} (${esc(p.unit)})</label><div class="quantity-stepper"><button type="button" data-quantity-step aria-label="Decrease quantity for ${esc(p.name)}" aria-disabled="true">−</button><input id="qty-${p.id}" type="number" min="1" max="999999" step="1" value="1"><button type="button" data-quantity-step aria-label="Increase quantity for ${esc(p.name)}">+</button></div><button class="btn dark" data-product="${p.id}">${purchaseLabel(p)}</button></div></div></article>`}
function addProduct(id,quantity){if(!quotationMode()&&priceReferences[id])return addShoppingProduct(id,quantity);const p=products.find(p=>p.id===id);if(!p)return;if(!Number.isInteger(quantity)||quantity<1||quantity>999999){toast('Enter a whole quantity between 1 and 999,999.');return}const existing=items.find(i=>i.productId===id&&!i.school);const total=Number(existing?.quantity||0)+quantity;if(total>999999){toast('This would exceed the maximum quantity of 999,999. Edit the basket first.');return}if(existing)existing.quantity=total;else items.push({productId:p.id,description:`${p.name} — ${p.summary}`,quantity,unit:p.unit});updateCount();showAdded(p,quantity,total)}
function bindProducts() {
  main.querySelectorAll('[data-product]').forEach(button => {
    const input = document.getElementById('qty-' + button.dataset.product);
    button.onclick = () => addProduct(button.dataset.product, Number(input.value));
  });
  main.querySelectorAll('.quantity-stepper').forEach(stepper => {
    const input = stepper.querySelector('input');
    const [decrease, increase] = stepper.querySelectorAll('[data-quantity-step]');
    function updateLimits() {
      decrease.setAttribute('aria-disabled', String(input.valueAsNumber <= Number(input.min)));
      increase.setAttribute('aria-disabled', String(input.valueAsNumber >= Number(input.max)));
    }
    for (const button of [decrease, increase]) {
      button.onclick = () => {
        if (button.getAttribute('aria-disabled') === 'true') return;
        if (button === decrease) input.stepDown();
        else input.stepUp();
        updateLimits();
      };
    }
    input.oninput = updateLimits;
    updateLimits();
  });
}
function productPage(id){const p=products.find(p=>p.id===id);if(!p&&retiredProducts.some(x=>x.id===id)){const retired=retiredProducts.find(x=>x.id===id),replacement=products.find(x=>x.id===retired.replacementId);return pageHero('Catalogue update','This product has been updated','Review the current product specifications and ordering unit before adding it to your quote.')+`<section class="section"><div class="wrap"><a class="btn dark" href="#product-${replacement.id}">View ${esc(replacement.name)}</a></div></section>`}if(!p)return pageHero('Catalogue','Product not found','Browse the catalogue to select a product.')+'<div class="wrap section"><a href="#stationery">Back to products</a></div>';return `<section class="section product-detail"><div class="wrap"><a class="breadcrumb" href="${catalogueHref()}">← Back to results</a><div class="product-detail-grid"><div class="detail-image">${productArt(p)}</div><div><span class="eyebrow">${p.catalogueImport||p.supplierReference?'Product details':'Sample product'}</span><h1>${p.name}</h1><p>${p.summary}</p>${priceMarkup(p,true)}<dl class="product-specifications">${Object.entries(p.specs).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>Order unit</dt><dd>${p.unit}</dd></div><div><dt>Brand</dt><dd>${esc(productBrand(p))}</dd></div></dl><label for="qty-${p.id}" class="qty-detail-label">Quantity (${p.unit.toLowerCase()})</label><div class="product-controls detail-controls"><input id="qty-${p.id}" type="number" min="1" max="999999" step="1" value="1"><button class="btn dark" data-product="${p.id}">${purchaseLabel(p,true)}</button></div><p class="help">${p.catalogueImport?importedProductPhotoNote(p):p.supplierReference?'Product photograph from the supplier catalogue. Packaging may vary. Availability and lead time will be confirmed in your quotation.':'Generated image for illustration. Final brand, specifications and availability to be confirmed.'}</p><a class="text-link" href="${quotationMode()||!priceReferences[p.id]?rfqHref('basket'):'#cart'}">${rfqBuyer()&&quotationMode()?'Review your RFQ basket':quotationMode()||!priceReferences[p.id]?'Review your quote basket':'Review your shopping cart'}</a></div></div></div></section>`}
function basketReference(line){const product=products.find(p=>p.id===line.productId),price=priceReferences[line.productId];return product&&line.unit===product.unit&&price?.currency==='ZAR'&&Number.isInteger(price.amountMinor)&&price.amountMinor>=0?price:null}
function basketPriceMarkup(line){if(rfqBuyer())return ''; const price=basketReference(line);return price?`<dl class="basket-line-prices"><div><dt>Indicative unit price</dt><dd>${esc(schoolMoney(price.amountMinor))} / ${esc(line.unit)}</dd></div><div><dt>Line total</dt><dd>${esc(schoolMoney(price.amountMinor*line.quantity))}</dd></div></dl>`:'<p class="basket-price-missing">Price by quotation — excluded from the subtotal.</p>'}
function basketPricingSummary(){if(rfqBuyer())return `<p class="rfq-pricing-note">Lepetse will review your requirements, determine pricing and email you a quotation.</p><p class="help">An RFQ requests pricing. It does not place an order or require payment.</p>`;const priced=items.filter(x=>basketReference(x)),missing=items.length-priced.length,total=priced.reduce((sum,line)=>sum+basketReference(line).amountMinor*line.quantity,0);return `<div class="basket-price-total"><span>${missing?'Indicative priced-item subtotal':'Indicative item total'}</span><strong>${priced.length?esc(schoolMoney(total)):'Price by quotation'}</strong></div><p class="basket-price-coverage">${priced.length} of ${items.length} item lines priced.${missing?` ${missing} ${missing===1?'line needs':'lines need'} pricing; this is not a complete total.`:''}</p><p class="help">Retail reference prices, not a confirmed Lepetse quotation. Delivery excluded. Applicable VAT and final pricing will be confirmed in your quotation.</p>`}
function updateBasketPrices(){if(rfqBuyer()){const summary=$('#basket-price-summary');if(summary)summary.innerHTML=basketPricingSummary();return;}const invalid=[...main.querySelectorAll('[data-basket-qty]')].some(input=>!input.value||!input.checkValidity());main.querySelectorAll('[data-basket-prices]').forEach(target=>{const i=Number(target.dataset.basketPrices),input=$('#basket-qty-'+i);target.innerHTML=input?.checkValidity()&&input.value?basketPriceMarkup(items[i]):'<p class="basket-price-missing">Enter a valid quantity to calculate this line.</p>'});const summary=$('#basket-price-summary');if(summary)summary.innerHTML=invalid?'<p class="basket-price-missing">Enter valid whole quantities to calculate the basket total.</p>':basketPricingSummary()}
function basketItemDetails(line,product){const meta=validatedSchoolMeta(line.school,line.productId);if(meta){const source=schoolPlan(meta.grade,meta.learners).find(x=>x.key===meta.key);return `<p><strong>School specification:</strong> ${esc(source.original)}</p><p><strong>Per learner:</strong> ${source.perLearner} × ${esc(source.unit)}</p>${source.difference?`<p><strong>Replacement reviewed:</strong> ${esc(source.difference)}</p>`:''}${schoolPackNote(source)?`<p>${esc(schoolPackNote(source))}</p>`:''}${source.quantity!==Number(line.quantity)?`<p><strong>Buyer-adjusted quantity:</strong> ${line.quantity} × ${esc(line.unit)}. Calculated school quantity: ${source.quantity} × ${esc(line.unit)}.</p>`:''}`;}return `<p>${esc(product?.summary||line.description)}</p>`}
function basketGroupedItems(){const groups=new Map();items.forEach((line,index)=>{const meta=validatedSchoolMeta(line.school,line.productId),key=meta?`${meta.school}:${meta.grade}:${meta.learners}`:'catalogue';if(!groups.has(key))groups.set(key,{meta,rows:[]});groups.get(key).rows.push({line,index})});return [...groups.values()].map((group,g)=>`<section class="basket-group${group.meta?'':' basket-catalogue-group'}" aria-labelledby="basket-group-${g}"><h2 id="basket-group-${g}" class="basket-group-title">${group.meta?`Glenanda Primary · Grade ${esc(group.meta.grade)}<span>${group.meta.learners} learner${group.meta.learners===1?'':'s'} · ${group.rows.length} item${group.rows.length===1?'':'s'}</span>`:'Catalogue items'}</h2>${group.rows.map(({line:x,index:i})=>{const p=products.find(p=>p.id===x.productId)||retiredProducts.find(p=>p.id===x.productId);return `<article class="basket-item">${p?`<div class="basket-thumb">${productArt(p)}</div>`:''}<div class="basket-description"><h3>${esc(p?.name||x.description)}</h3><div class="basket-item-details" data-basket-details="${i}">${basketItemDetails(x,p)}</div><p>Order unit: ${esc(x.unit||'Specify pack size in the request')}</p><div data-basket-prices="${i}">${basketPriceMarkup(x)}</div></div><div><label for="basket-qty-${i}">Quantity</label><input id="basket-qty-${i}" type="number" min="1" max="999999" step="1" value="${esc(x.quantity)}" data-basket-qty="${i}"><button class="remove-item" data-basket-remove="${i}">Remove</button></div></article>`}).join('')}</section>`).join('')}
function quoteBasketMarkup(){if(!items.length)return pageHero('Quotation request','Your quote basket is empty','Choose products and quantities, or attach an existing stationery list.')+`<section class="section"><div class="wrap"><div class="empty empty-basket"><h2>Start your enquiry</h2><p>Catalogue selections will be saved on this device. No order is placed until pricing and terms are agreed.</p><a class="btn dark" href="#stationery?mode=quote">Browse products</a><a class="btn outline" href="#upload">Upload your list</a></div></div></section>`;return `<section class="catalogue-heading"><div class="wrap"><span class="eyebrow">Quotation request</span><h1>Your quote basket</h1><p>Review specifications, quantities and order units before entering your contact and delivery details.</p></div></section><section class="section basket-section"><div class="wrap basket-layout"><div>${items.length?`<div class="basket-items">${basketGroupedItems()}</div><div class="basket-footer-actions"><a class="text-link" href="#stationery?mode=quote">Continue browsing</a><button class="clear-filters" id="clear-basket">Clear basket</button></div>`:`<div class="empty"><h2>Your quote basket is empty</h2><p>Start with products from the catalogue, or upload an existing list. No order has been placed.</p><a class="btn dark" href="#stationery?mode=quote">Browse products</a><a class="btn outline" href="#upload">Upload your list</a></div>`}</div><aside class="basket-summary"><h2>Request summary</h2><p class="basket-storage-note">${items.some(x=>retiredProducts.some(p=>p.id===x.productId&&!p.schoolRequirement))?'Some selections are from the previous catalogue. Their original descriptions, quantities and units have been retained. Review them before requesting a quote.':basketStorageUnavailable?'Device storage is unavailable. Keep this page open to retain your selections.':'Catalogue selections are saved on this device. Contact details and attachments are not saved.'}</p><dl><div><dt>Item lines</dt><dd>${items.length}</dd></div><div><dt>Availability</dt><dd>To be confirmed</dd></div><div><dt>Delivery charges</dt><dd>Subject to location</dd></div></dl><div id="basket-price-summary" aria-live="polite">${basketPricingSummary()}</div>${items.length?'<button class="btn dark" id="basket-continue">Continue to enquiry</button>':''}<a class="btn outline" href="#upload">Upload your list</a><p class="help">${rfqSubmissionAvailable()?'Continue to contact and delivery details, then review and submit your RFQ.':'Preview only: prepare a request summary. Online submission is not connected on this version.'}</p></aside></div></section>`}
function basket(){let html=quoteBasketMarkup();if(quoteBasketBuyer()==='schools')html=html.replaceAll('href="#stationery?mode=quote"',`href="${rfqHref('stationery')}"`).replaceAll('href="#upload"','href="#upload?buyer=schools"');if(rfqBuyer())html=html.replaceAll('Your quote basket','Your RFQ basket').replaceAll('Quotation request','Request for quotation').replaceAll('Continue to enquiry','Continue to RFQ details').replaceAll('href="#stationery?mode=quote"',`href="${rfqHref('stationery')}"`).replaceAll('href="#upload"',`href="#upload?buyer=${rfqBuyer()}"`);return html}
function bindBasket(){$('#clear-basket')?.addEventListener('click',clearBasketPrompt);main.querySelectorAll('[data-basket-qty]').forEach(e=>{e.oninput=()=>{const q=Number(e.value);if(Number.isInteger(q)&&q>=1&&q<=999999){const line=items[Number(e.dataset.basketQty)];line.quantity=q;const meta=validatedSchoolMeta(line.school,line.productId),product=products.find(p=>p.id===line.productId);if(meta&&product){line.description=schoolBasketDescription(product,meta,q);e.closest('.basket-item').querySelector('[data-basket-details]').innerHTML=basketItemDetails(line,product);}saveBasket()}updateBasketPrices()};e.onchange=()=>{if(!e.checkValidity()){e.value=items[Number(e.dataset.basketQty)].quantity;toast('Enter a whole quantity between 1 and 999,999.')}updateBasketPrices()}});main.querySelectorAll('[data-basket-remove]').forEach(e=>e.onclick=()=>{items.splice(Number(e.dataset.basketRemove),1);main.innerHTML=basket();bindBasket();updateCount()});$('#basket-continue')?.addEventListener('click',()=>{const bad=[...main.querySelectorAll('[data-basket-qty]')].find(e=>!e.value||!e.checkValidity());if(bad){bad.reportValidity();return}capture();step=0;location.hash=rfqHref('quote')})}
